export function Filter({ column, table, placeholder, columnFiltersShow }: { column: Column<any, any>; table: Table<any>; placeholder: any; columnFiltersShow: any; }): JSX.Element {
    const columnFilterValue = column.getFilterValue();
    const [inputValue, setInputValue] = React.useState<any>(columnFilterValue ?? '');
    const debouncedValue = useDebounce(inputValue, 600);
    const canSort = column.getCanSort() && columnFiltersShow !== false;
    React.useEffect(() => {
        setInputValue(columnFilterValue ?? '');
    }, [columnFilterValue]);
    React.useEffect(() => { column.setFilterValue(debouncedValue); }, [debouncedValue, column]);
    return (
        <>
            <input
                readOnly={columnFiltersShow === false ? true : false}
                className={
                    columnFiltersShow === false
                        ? "m-1 h-[30px] w-full min-w-0 flex-1 border-none bg-transparent text-sm font-normal text-[#0a0a0a] outline-none placeholder:font-normal placeholder:text-[#0a0a0a] placeholder:opacity-100"
                        : `m-1 h-[30px] w-full min-w-0 flex-1 rounded-none border border-[#bdbdbd] bg-white px-[3.5px] py-[3.5px] text-sm text-[#444] font-normal placeholder:font-normal outline-none ${canSort ? "pr-5" : "pr-2"}`
                }
                type="text"
                value={inputValue}
                onChange={(e) => setInputValue(e.target.value)}
                placeholder={placeholder?.placeholder}
            />
            {inputValue && (
                <span
                    className={`absolute top-1/2 z-[1] h-5 w-4 -translate-y-1/2 cursor-pointer bg-white text-center leading-5 text-[#2F5596] ${canSort ? "right-5" : "right-2"}`}
                    onClick={() => setInputValue('')}
                >
                    ×
                </span>
            )}
            <span className="pointer-events-none absolute left-full top-1/2 z-50 ml-1 hidden -translate-y-1/2 whitespace-nowrap rounded bg-black px-2 py-1 text-xs font-light text-white group-hover:block"> {placeholder?.placeholder}</span>
        </>
    );
}
export function IndeterminateCheckbox(
    {
        indeterminate,
        className = "",
        ...rest
    }: { indeterminate?: boolean } & HTMLProps<HTMLInputElement>) {
    const ref = React.useRef<HTMLInputElement>(null!);
    React.useEffect(() => {
        if (typeof indeterminate === "boolean") {
            ref.current.indeterminate = !rest.checked && indeterminate;
        }
    }, [ref, indeterminate]);
    return (
        <input
            type="checkbox"
            ref={ref}
            className={className + "h-4 w-4 accent-[#2F5596] cursor-pointer"}
            {...rest}
        />
    );
}
