(() => {
  const rows = Array.from(document.querySelectorAll('tr, div[role="row"]'));
  const c002Row = rows.find(r => r.textContent.includes('C002') && r.textContent.includes('Admin Tool'));
  const svgs = Array.from(c002Row.querySelectorAll('svg'));
  return svgs.map(s => {
    const cs = getComputedStyle(s);
    const parent = s.closest('div');
    const pcs = parent ? getComputedStyle(parent) : null;
    return {
      viewBox: s.getAttribute('viewBox'),
      inlineStyle: s.getAttribute('style'),
      color: cs.color,
      display: cs.display,
      visibility: cs.visibility,
      opacity: cs.opacity,
      width: cs.width,
      height: cs.height,
      parentDisplay: pcs ? pcs.display : null,
      parentVisibility: pcs ? pcs.visibility : null,
    };
  });
})()

