const getFirstColCell = ({ setExpanded, hasCheckbox, hasCustomExpanded, hasExpanded }: any) => {
    return ({ row, getValue, table }: any) => (
        <div className="flex items-center">
            {hasExpanded && row.getCanExpand() && (
                <div className="border-0 flex items-center" {...{ onClick: row.getToggleExpandedHandler(), style: { cursor: "pointer" }, }}>
                    {row.getIsExpanded() ? <SlArrowDown title={'Collapse ' + `${row.original.Title}` + ' childs'} style={{ color: `${row?.original?.PortfolioType?.Color}`, width: '12px' }} /> : <SlArrowRight title={'Expand ' + `${row.original.Title}` + ' childs'} style={{ color: `${row?.original?.PortfolioType?.Color}`, width: '12px' }} />}
                </div>
            )}{" "}
            {hasCheckbox && row?.original?.Title != "Others" && !row?.original?.hideCheckbox && (
                <span className="flex items-center" style={{ marginLeft: hasExpanded && row.getCanExpand() ? '11px' : hasExpanded !== true ? '0px' : '23px' }}> <IndeterminateCheckbox {...{ checked: row.getIsSelected(), indeterminate: row.getIsSomeSelected(), onChange: row.getToggleSelectedHandler(), }} />{" "}</span>
            )}
            {hasCustomExpanded && <div>
                {((row.getCanExpand() &&
                    row.subRows?.length !== row.original.subRows?.length) ||
                    !row.getCanExpand() ||
                    forceExpanded.includes(row.id)) &&
                    row.original.subRows?.length ? (
                    <div className="mx-1 flex items-center"
                        {...{
                            onClick: () => {
                                if (!forceExpanded.includes(row.id)) {
                                    // eslint-disable-next-line no-console
                                    console.log('[+icon] click', {
                                        title: row?.original?.Title,
                                        rowId: row.id,
                                        rowSubRowsLenBefore: row.subRows?.length,
                                        originalSubRowsLen: row.original?.subRows?.length,
                                    });
                                    const coreIds = table.getCoreRowModel().rowsById;
                                    // eslint-disable-next-line no-console
                                    console.log('[+icon] coreIds lookup', {
                                        rowId: row.id,
                                        coreRowFound: !!coreIds[row.id],
                                        coreRowTitle: coreIds[row.id]?.original?.Title,
                                        coreRowSubRowsLen: coreIds[row.id]?.subRows?.length,
                                        coreRowMatchesThisRow: coreIds[row.id] === row,
                                    });
                                    row.subRows = coreIds[row.id].subRows;
                                    // eslint-disable-next-line no-console
                                    console.log('[+icon] after assign row.subRows', {
                                        rowSubRowsLenAfter: row.subRows?.length,
                                    });
                                    const rowModel = table.getRowModel();
                                    // Only inject DIRECT children — deeper descendants stay
                                    // collapsed until their own + icon is clicked.
                                    row.subRows?.forEach((elem: any) => {
                                        if (!rowModel.rowsById[elem.id]) {
                                            rowModel.flatRows.push(elem);
                                            rowModel.rowsById[elem.id] = elem;
                                        }
                                    });
                                    const rowDepth = row.id.split(".").length;
                                    const temp = Object.keys(coreIds).filter(
                                        (item: any) =>
                                            item === row.id ||
                                            (item.startsWith(row.id + ".") &&
                                                item.split(".").length === rowDepth + 1)
                                    );
                                    forceExpanded = [...forceExpanded, ...temp];
                                    // eslint-disable-next-line no-console
                                    console.log('[+icon] forceExpanded set, calling setExpanded', {
                                        forceExpanded,
                                    });
                                    setExpanded((prev: any) => ({
                                        ...prev,
                                        [row.id]: true,
                                    }));
                                    // forceExpanded is a plain module-level array, not tracked
                                    // by TanStack's memoized filtered row model — bump columnFilters
                                    // with a new reference so filtering re-runs and picks it up.
                                    table.setColumnFilters((prev: any) => (Array.isArray(prev) ? [...prev] : prev));
                                } else {
                                    // eslint-disable-next-line no-console
                                    console.log('[+icon] already forceExpanded, using plain toggle handler', {
                                        title: row?.original?.Title,
                                        rowId: row.id,
                                    });
                                    row.getToggleExpandedHandler()();
                                }
                            },
                            style: { cursor: "pointer" },
                        }}
                    >
                        {!row.getCanExpand() ||
                            (row.getCanExpand() &&
                                row.subRows?.length !== row.original.subRows?.length)
                            ? <FaPlus style={{ fontSize: '10px', color: `${row?.original?.PortfolioType?.Color}` }} />
                            : row.getIsExpanded()
                                ? <FaMinus style={{ color: `${row?.original?.PortfolioType?.Color}` }} />
                                : <FaPlus style={{ fontSize: '10px', color: `${row?.original?.PortfolioType?.Color}` }} />}
                    </div>
                ) : (
                    ""
                )}{" "}
            </div>}
            {getValue()}
        </div>
    );
};
