(() => {
  const input = document.querySelector('input[placeholder="Title"]');
  if (!input) return 'not found';
  const nativeSetter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
  nativeSetter.call(input, 'Admin Tool');
  input.dispatchEvent(new Event('input', { bubbles: true }));
  return 'set';
})()

(() => {
  window.__capturedLogs = [];
  const orig = console.log.bind(console);
  console.log = function(...args) {
    if (typeof args[0] === 'string' && (args[0].includes('[+icon]') || args[0].includes('[icon-gate]'))) {
      window.__capturedLogs.push(args);
    }
    return orig(...args);
  };
  return 'patched';
})()

