    const temp = Object.keys(coreIds).filter(
        (item: any) =>
            item === row.id ||
            item.startsWith(row.id + ".")
    );
    forceExpanded = [...forceExpanded, ...temp];
    setExpanded((prev: any) => ({
        ...prev,
        [row.id]: true,
    }));
} else {
    row.getToggleExpandedHandler()();
}

