    const { WebFullUrl: currentSiteUrl } = await pageContext();
try{
    if (dataType === "AllSites") {
        let AllSiteUrlData = await getAllSiteUrl()
        let AllDocumentData: any = []
                const allPromises = AllSiteUrlData.map((val: any) => loadAllSitesDocuments(val, filter));
               const allResults: any = await Promise.all(allPromises);
                AllDocumentData = allResults.flat();
                if (AllDocumentData?.length > 0) {
                                AllDocumentData.forEach((item: any, index: any) => {
                                    if (item != undefined) {
                                        item.uniqueID = parseInt(`${index + 1}`); // Add unique ID
                                    }

                                });
                            }
                return AllDocumentData;
    }else{

    const Alldata = { siteUrl: currentSiteUrl };
  let  allDcoc =await loadAllSitesDocuments(Alldata, filter);
    return allDcoc;
    }
    }catch(error) {

    }
}
